-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_attendance AS SELECT attendance.link_to_event AS link_to_event, attendance.link_to_member AS link_to_member, link_to_member.first_name AS link_to_member_first_name, link_to_member.last_name AS link_to_member_last_name, link_to_member.email AS link_to_member_email, link_to_member.position AS link_to_member_position, link_to_member.t_shirt_size AS link_to_member_t_shirt_size, link_to_member.phone AS link_to_member_phone, link_to_member.zip AS link_to_member_zip, link_to_member.link_to_major AS link_to_member_link_to_major, link_to_event.event_name AS link_to_event_event_name, link_to_event.event_date AS link_to_event_event_date, link_to_event.type AS link_to_event_type, link_to_event.notes AS link_to_event_notes, link_to_event.location AS link_to_event_location, link_to_event.status AS link_to_event_status FROM attendance LEFT JOIN member AS link_to_member ON attendance.link_to_member = link_to_member.member_id LEFT JOIN event AS link_to_event ON attendance.link_to_event = link_to_event.event_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_budget AS SELECT budget.budget_id AS budget_id, budget.category AS category, budget.spent AS spent, budget.remaining AS remaining, budget.amount AS amount, budget.event_status AS event_status, budget.link_to_event AS link_to_event, link_to_event.event_name AS link_to_event_event_name, link_to_event.event_date AS link_to_event_event_date, link_to_event.type AS link_to_event_type, link_to_event.notes AS link_to_event_notes, link_to_event.location AS link_to_event_location, link_to_event.status AS link_to_event_status FROM budget LEFT JOIN event AS link_to_event ON budget.link_to_event = link_to_event.event_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_expense AS SELECT expense.expense_id AS expense_id, expense.expense_description AS expense_description, expense.expense_date AS expense_date, expense.cost AS cost, expense.approved AS approved, expense.link_to_member AS link_to_member, expense.link_to_budget AS link_to_budget, link_to_member.first_name AS link_to_member_first_name, link_to_member.last_name AS link_to_member_last_name, link_to_member.email AS link_to_member_email, link_to_member.position AS link_to_member_position, link_to_member.t_shirt_size AS link_to_member_t_shirt_size, link_to_member.phone AS link_to_member_phone, link_to_member.zip AS link_to_member_zip, link_to_member.link_to_major AS link_to_member_link_to_major, link_to_budget.category AS link_to_budget_category, link_to_budget.spent AS link_to_budget_spent, link_to_budget.remaining AS link_to_budget_remaining, link_to_budget.amount AS link_to_budget_amount, link_to_budget.event_status AS link_to_budget_event_status, link_to_budget.link_to_event AS link_to_budget_link_to_event, link_to_budget_link_to_event.event_name AS link_to_budget_link_to_event_event_name, link_to_budget_link_to_event.event_date AS link_to_budget_link_to_event_event_date, link_to_budget_link_to_event.type AS link_to_budget_link_to_event_type, link_to_budget_link_to_event.notes AS link_to_budget_link_to_event_notes, link_to_budget_link_to_event.location AS link_to_budget_link_to_event_location, link_to_budget_link_to_event.status AS link_to_budget_link_to_event_status FROM expense LEFT JOIN member AS link_to_member ON expense.link_to_member = link_to_member.member_id LEFT JOIN budget AS link_to_budget ON expense.link_to_budget = link_to_budget.budget_id LEFT JOIN event AS link_to_budget_link_to_event ON link_to_budget.link_to_event = link_to_budget_link_to_event.event_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_income AS SELECT income.income_id AS income_id, income.date_received AS date_received, income.amount AS amount, income.source AS source, income.notes AS notes, income.link_to_member AS link_to_member, link_to_member.first_name AS link_to_member_first_name, link_to_member.last_name AS link_to_member_last_name, link_to_member.email AS link_to_member_email, link_to_member.position AS link_to_member_position, link_to_member.t_shirt_size AS link_to_member_t_shirt_size, link_to_member.phone AS link_to_member_phone, link_to_member.zip AS link_to_member_zip, link_to_member.link_to_major AS link_to_member_link_to_major FROM income LEFT JOIN member AS link_to_member ON income.link_to_member = link_to_member.member_id;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_member AS SELECT member.member_id AS member_id, member.first_name AS first_name, member.last_name AS last_name, member.email AS email, member.position AS position, member.t_shirt_size AS t_shirt_size, member.phone AS phone, member.zip AS zip, member.link_to_major AS link_to_major, zip.type AS zip_type, zip.city AS zip_city, zip.county AS zip_county, zip.state AS zip_state, zip.short_state AS zip_short_state, link_to_major.major_name AS link_to_major_major_name, link_to_major.department AS link_to_major_department, link_to_major.college AS link_to_major_college FROM member LEFT JOIN zip_code AS zip ON member.zip = zip.zip_code LEFT JOIN major AS link_to_major ON member.link_to_major = link_to_major.major_id;

-- origin=oracle_fan row_preserving=False check=rows_differ(348 vs 326)
CREATE VIEW v_attendance_event_income_member AS SELECT attendance.link_to_event AS link_to_event, attendance.link_to_member AS link_to_member, member.first_name AS member_first_name, member.last_name AS member_last_name, member.email AS member_email, member.position AS member_position, member.t_shirt_size AS member_t_shirt_size, member.phone AS member_phone, member.zip AS member_zip, member.link_to_major AS member_link_to_major, event.event_name AS event_name, event.event_date AS event_date, event.type AS event_type, event.notes AS event_notes, event.location AS event_location, event.status AS event_status, income.income_id AS income_id, income.date_received AS income_date_received, income.amount AS income_amount, income.source AS income_source, income.notes AS income_notes FROM attendance LEFT JOIN member AS member ON attendance.link_to_member = member.member_id LEFT JOIN event AS event ON attendance.link_to_event = event.event_id LEFT JOIN income AS income ON member.member_id = income.link_to_member;
